using System.Collections.Concurrent;
using System.ComponentModel;
using System.Net;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Build the chat client through the MEAI abstraction
// ---------------------------------------------------------------------------
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// ---------------------------------------------------------------------------
// Tool instances
// ---------------------------------------------------------------------------
var notebook = new Notebook();
var webSearcher = new WebSearcher();

// ---------------------------------------------------------------------------
// Register tools via AIFunctionFactory
// ---------------------------------------------------------------------------
IList<AITool> tools =
[
    AIFunctionFactory.Create(webSearcher.SearchWeb),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
];

// ---------------------------------------------------------------------------
// Create the agent
// ---------------------------------------------------------------------------
const string systemPrompt = """
    You are a research agent. Your job is to research a topic thoroughly
    using the tools available to you.

    Workflow:
    1. Break the topic into 3-5 key subtopics or questions.
    2. Use the SearchWeb tool to find information on each subtopic.
    3. Use the AddNote tool to record important findings as you go.
    4. After finishing your research, use GetNotes to review everything.
    5. Write a comprehensive summary with the key takeaways.

    Be thorough but focused. Always take notes on key findings before
    moving to the next search.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: systemPrompt,
    name: "ResearchAgent",
    description: "Researches a topic using web search and note-taking tools",
    tools: tools);

// ---------------------------------------------------------------------------
// Get the research topic
// ---------------------------------------------------------------------------
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");
Console.WriteLine(new string('─', 60));

// ---------------------------------------------------------------------------
// Run the agent
// ---------------------------------------------------------------------------
var session = await agent.CreateSessionAsync(
    conversationId: Guid.NewGuid().ToString());

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var result = await agent.RunAsync(
    $"Research the following topic and provide a detailed summary: {topic}",
    session,
    runOptions);

// Print the final response
foreach (var message in result.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

// ---------------------------------------------------------------------------
// Show collected notes
// ---------------------------------------------------------------------------
Console.WriteLine();
Console.WriteLine(new string('─', 60));
Console.WriteLine("📝 Notes collected during research:");
Console.WriteLine(new string('─', 60));

var notes = notebook.Notes;
if (notes.Count == 0)
{
    Console.WriteLine("  (no notes were recorded)");
}
else
{
    for (var i = 0; i < notes.Count; i++)
    {
        Console.WriteLine($"  {i + 1}. {notes[i]}");
    }
}

return;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(topic)
        ? throw new InvalidOperationException("No topic provided.")
        : topic;
}

// ═══════════════════════════════════════════════════════════════════════════
// Tool: Note-taking
// ═══════════════════════════════════════════════════════════════════════════
sealed class Notebook
{
    private readonly ConcurrentBag<string> _notes = new();

    public IReadOnlyList<string> Notes => [.. _notes];

    [Description("Saves a research note. Use this to record key findings during research.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved. Total notes: {_notes.Count}";
    }

    [Description("Retrieves all research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.IsEmpty)
            return "No notes recorded yet.";

        var sb = new StringBuilder();
        var i = 1;
        foreach (var note in _notes)
            sb.AppendLine($"{i++}. {note}");

        return sb.ToString();
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// Tool: Web search
// ═══════════════════════════════════════════════════════════════════════════
sealed class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
    };

    [Description("Searches the web for information on a query. Returns text results.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite?q={encoded}";

            var html = await Http.GetStringAsync(url, cancellationToken);
